function longestLetterChain(words: string[]): number {
  const w = [...words].sort((a, b) => a.length - b.length);
  // can x become y by inserting one letter?
  const stepsTo = (x: string, y: string): boolean => {
    if (y.length !== x.length + 1) return false;
    let i = 0, skipped = false;
    for (let j = 0; j < y.length; j++) {
      if (i < x.length && x[i] === y[j]) i++;
      else if (skipped) return false;
      else skipped = true;
    }
    return true;
  };
  const best = new Array(w.length).fill(1);
  let ans = 1;
  for (let j = 0; j < w.length; j++) {
    for (let i = 0; i < j; i++) if (stepsTo(w[i], w[j])) best[j] = Math.max(best[j], best[i] + 1);
    ans = Math.max(ans, best[j]);
  }
  return ans;
}

