class Solution:
    def longestLetterChain(self, words: List[str]) -> int:
        w = sorted(words, key=len)

        def steps_to(x, y):
            if len(y) != len(x) + 1:
                return False
            i, skipped = 0, False
            for c in y:
                if i < len(x) and x[i] == c:
                    i += 1
                elif skipped:
                    return False
                else:
                    skipped = True
            return True

        best = [1] * len(w)
        for j in range(len(w)):
            for i in range(j):
                if steps_to(w[i], w[j]):
                    best[j] = max(best[j], best[i] + 1)
        return max(best)

