function longestLetterChain(words: string[]): number {
  const best = new Map<string, number>();
  let ans = 1;
  for (const w of [...words].sort((a, b) => a.length - b.length)) {
    let cur = 1;
    for (let i = 0; i < w.length; i++) {
      const prev = best.get(w.slice(0, i) + w.slice(i + 1));
      if (prev !== undefined) cur = Math.max(cur, prev + 1);
    }
    best.set(w, cur);
    ans = Math.max(ans, cur);
  }
  return ans;
}

